"use server";

import { z } from "zod";

import { MessageSchema } from "@/lib/chatbot/message-schema";
import { sql } from "@/lib/db";

// nanoid ids generated by the chat widget for each visit.
const ChatIdSchema = z.string().regex(/^[\w-]{10,64}$/);
const ConversationSchema = z
  .array(MessageSchema.extend({ text: z.string().max(8000) }))
  .max(200);

/** Stores the latest state of a visitor's chatbot conversation. */
export async function saveConversation(
  chatId: string,
  messages: unknown,
): Promise<void> {
  const id = ChatIdSchema.parse(chatId);
  const conversation = ConversationSchema.parse(messages);

  await sql`
    insert into chatbot_conversations (chat_id, messages)
    values (${id}, ${JSON.stringify(conversation)}::jsonb)
    on conflict (chat_id)
    do update set messages = excluded.messages, updated_at = now()
  `;
}
